// Hazard spawn config
const SAFE_RADIUS = 150; // avoid spawning too close to player
let spawnTimer = 0;
const SPAWN_INTERVAL = 1.5; // seconds
// === END STATE =========================================================

// === CONFIG =============================================================
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");
let loopId = null;
let lastTime = performance.now();
// === END CONFIG =========================================================

// === LOOP ===============================================================
function update(dt) {
  if (phase !== "playing") return;
  // Player movement based on keys
  const accel = 800; // px/sec^2
  const maxSpeed = 400; // px/sec

  spawnTimer = SPAWN_INTERVAL;
  // Random angle and distance
  const angle = Math.random() * Math.PI * 2;
  const distance = Math.max(SAFE_RADIUS, Math.hypot(canvas.width, canvas.height));
  const x = player.x + Math.cos(angle) * distance;
  const y = player.y + Math.sin(angle) * distance;
  const speed = 150; // px/sec
